function openQuotationDetail(id,productName){const quotation=quotationById(id);const modal=document.getElementById('quotationDetailModal');if(!quotation||!modal)return;closeProductPickers();modal.querySelector('[data-quotation-name]').textContent=quotation.name+'（'+quotation.code+'）';const option=[...document.querySelectorAll('[data-product-option][data-quotation-id="'+id+'"]')].find(item=>item.dataset.productName===productName);const products=[{name:productName||option?.dataset.productName||'当前商品',salesSpec:option?.dataset.salesSpec||'500g/斤',price:option?.dataset.price||'—',unit:option?.dataset.salesUnit||'件',current:true},{name:'时令蔬菜组合',salesSpec:'5kg/箱',price:'36.00',unit:'箱'},{name:'食堂常用辅料',salesSpec:'1件/件',price:'28.00',unit:'件'}];const body=modal.querySelector('[data-quotation-products]');body.replaceChildren();products.forEach(product=>{const row=document.createElement('tr');if(product.current)row.className='quotation-product-highlight';const name=document.createElement('td');name.textContent=product.name;if(product.current){const mark=document.createElement('span');mark.className='quotation-current-mark';mark.textContent='当前商品';name.appendChild(mark)}[name,product.salesSpec,'¥'+product.price+'/'+product.unit].forEach(value=>{if(value instanceof HTMLElement)row.appendChild(value);else{const cell=document.createElement('td');cell.textContent=value;row.appendChild(cell)}});body.appendChild(row)});modal.classList.add('open');modal.setAttribute('aria-hidden','false');requestAnimationFrame(()=>body.querySelector('.quotation-product-highlight')?.scrollIntoView({block:'center'}))}
function normalizeCustomerNote(value=''){const chars=Array.from(String(value).replace(/\\r?\\n/g,'')).slice(0,150);const lines=[];for(let index=0;index<chars.length;index+=20)lines.push(chars.slice(index,index+20).join(''));return lines.join('\\n')}
function syncCustomerNoteEmptyState(card,editing=false){if(!card)return;const textarea=card.querySelector('[data-customer-note-input]');const empty=!(textarea?.value||'').trim();card.classList.toggle('is-empty',empty&&!editing);if(empty){card.classList.remove('is-expanded');const display=card.querySelector('[data-customer-note-display]');if(display){display.textContent='显示全部';display.setAttribute('aria-expanded','false')}}}
function toggleCustomerNoteDisplay(trigger){const card=trigger.closest('.customer-note-card');if(!card)return;const expanded=card.classList.toggle('is-expanded');trigger.textContent=expanded?'收起':'显示全部';trigger.setAttribute('aria-expanded',String(expanded));const textarea=card.querySelector('[data-customer-note-input]');if(textarea)textarea.scrollTop=0}
