function saveCustomerNote(modal,value){if(!modal)return;const note=normalizeCustomerNote(value).trim();const row=[...document.querySelectorAll('tr[data-customer-id]')].find(item=>item.dataset.customerId===modal.dataset.customerId);if(row){const copy=row.querySelector('[data-customer-note-text]');const edit=row.querySelector('[data-customer-note-edit]');if(copy){copy.textContent=note||'暂无便签';copy.classList.toggle('customer-note-empty',!note);copy.title=note}if(edit)edit.dataset.customerNote=note}modal.dataset.savedNote=note}
function linkedRoot(el){return el&&el.closest('.linked-detail')}
function sourceSequence(root){return [...root.querySelectorAll('.source-box[data-source="1"]')].sort((a,b)=>(parseFloat(a.style.top)||0)-(parseFloat(b.style.top)||0)||(parseFloat(a.style.left)||0)-(parseFloat(b.style.left)||0))}
function refreshSourceStepper(root,box){if(!root)return;const boxes=sourceSequence(root);const anchor=box&&boxes.find(x=>x.dataset.item===box.dataset.item);const index=anchor?boxes.indexOf(anchor):-1;root.querySelectorAll('[data-source-step]').forEach(button=>{button.disabled=button.dataset.sourceStep==='prev'?index<=0:index<0||index>=boxes.length-1})}
function setSourceImageView(root,view){if(!root)return;const canvas=root.querySelector('.source-canvas');const switcher=root.querySelector('[data-source-view-switch]');if(!canvas||switcher?.hidden)return;view=view==='original'?'original':'corrected';canvas.dataset.imageView=view;switcher.querySelectorAll('[data-source-view]').forEach(button=>{const active=button.dataset.sourceView===view;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))});setSourceZoom(root,1);const viewport=root.querySelector('.source-image-viewport');if(viewport){viewport.scrollLeft=0;viewport.scrollTop=0}if(view==='original')root.querySelectorAll('[data-source-step]').forEach(button=>button.disabled=true);else{const active=root.querySelector('.source-box.active');if(active)refreshSourceStepper(root,active);else{const steps=[...root.querySelectorAll('[data-source-step]')];steps.forEach(button=>button.disabled=button.dataset.sourceStep==='prev'||!sourceSequence(root).length)}}}
function refreshSourceEnhancement(root,source){if(!root)return;const chip=root.querySelector('[data-source-enhancement-chip]');const switcher=root.querySelector('[data-source-view-switch]');if(!chip||!switcher)return;const choice=root.querySelector('[data-source-choice="'+String(source||1)+'"]');const corrected=choice?.dataset.enhancementState==='processed';chip.hidden=!corrected;switcher.hidden=!corrected;chip.textContent='已自动校正';const tip='当前图片已进行倾斜校正，可切换查看原图和校正图。';chip.dataset.tip=tip;chip.title=tip;chip.setAttribute('aria-label',tip);if(!corrected){const canvas=root.querySelector('.source-canvas');if(canvas)canvas.dataset.imageView='corrected'}}
function setSourceZoom(root,value){if(!root)return 1;const canvas=root.querySelector('.source-canvas');if(!canvas)return 1;const zoom=Math.max(1,Math.min(3,Math.round(Number(value||1)*100)/100));canvas.dataset.zoom=String(zoom);canvas.style.width=Math.round(zoom*100)+'%';const valueLabel=root.querySelector('[data-source-zoom-value]');if(valueLabel)valueLabel.textContent=Math.round(zoom*100)+'%';root.querySelectorAll('[data-source-zoom]').forEach(button=>{button.disabled=button.dataset.sourceZoom==='out'?zoom<=1:button.dataset.sourceZoom==='in'?zoom>=3:false});return zoom}
function zoomSourceAt(root,value,clientX,clientY){if(!root)return 1;const viewport=root.querySelector('.source-image-viewport');const canvas=root.querySelector('.source-canvas');if(!viewport||!canvas)return setSourceZoom(root,value);const rect=viewport.getBoundingClientRect();const offsetX=clientX-rect.left;const offsetY=clientY-rect.top;const ratioX=(viewport.scrollLeft+offsetX)/Math.max(canvas.scrollWidth,1);const ratioY=(viewport.scrollTop+offsetY)/Math.max(canvas.scrollHeight,1);const zoom=setSourceZoom(root,value);requestAnimationFrame(()=>{viewport.scrollLeft=Math.max(0,ratioX*canvas.scrollWidth-offsetX);viewport.scrollTop=Math.max(0,ratioY*canvas.scrollHeight-offsetY)});return zoom}
function centerSourceBox(root,box,autoZoom=false){if(!root||!box)return;const viewport=root.querySelector('.source-image-viewport');if(!viewport)return;if(autoZoom){const widthRatio=(parseFloat(box.style.width)||35)/100;setSourceZoom(root,Math.max(1.6,Math.min(3,.72/widthRatio)))}requestAnimationFrame(()=>requestAnimationFrame(()=>viewport.scrollTo({left:Math.max(0,box.offsetLeft+box.offsetWidth/2-viewport.clientWidth/2),top:Math.max(0,box.offsetTop+box.offsetHeight/2-viewport.clientHeight/2),behavior:'smooth'})))}
function focusSourceBox(root,box){if(!root||!box)return;const item=box.dataset.item;const source=String(box.dataset.source||1);root.querySelectorAll('.source-box').forEach(x=>{x.style.display=x.dataset.source===source?'block':'none';x.classList.toggle('active',x===box)});refreshSourceStepper(root,box);refreshSourceEnhancement(root,source);centerSourceBox(root,box,true);const row=root.querySelector('[data-link-row][data-item="'+item+'"]');if(box.dataset.unlinked==='true'){root.querySelectorAll('[data-link-row]').forEach(x=>x.classList.remove('link-active'));root.querySelectorAll('.source-choice').forEach(x=>{x.classList.toggle('active',x.dataset.sourceChoice==='1');x.hidden=x.dataset.sourceChoice!=='1'});toast('该原图区域暂无对应商品，请核对是否漏单');return}if(box.classList.contains('deleted')||!row||row.hidden){root.querySelectorAll('[data-link-row]').forEach(x=>x.classList.remove('link-active'));root.querySelectorAll('.source-choice').forEach(x=>{x.classList.toggle('active',x.dataset.sourceChoice==='1');x.hidden=x.dataset.sourceChoice!=='1'});toast('对应商品已删除');return}activateSource(root,item,source,true);row.scrollIntoView({behavior:'smooth',block:'center'})}
function stepSource(root,direction){const boxes=sourceSequence(root);if(!boxes.length)return;const active=root.querySelector('.source-box.active');const anchor=active&&boxes.find(x=>x.dataset.item===active.dataset.item);let index=anchor?boxes.indexOf(anchor):(direction>0?-1:boxes.length);index=Math.max(0,Math.min(boxes.length-1,index+direction));focusSourceBox(root,boxes[index])}
document.addEventListener('click',e=>{const viewButton=e.target.closest('[data-source-view]');if(viewButton){e.stopImmediatePropagation();setSourceImageView(linkedRoot(viewButton),viewButton.dataset.sourceView);return}const zoomButton=e.target.closest('[data-source-zoom]');if(zoomButton){e.stopImmediatePropagation();const root=linkedRoot(zoomButton);const canvas=root?.querySelector('.source-canvas');const current=Number(canvas?.dataset.zoom||1);const mode=zoomButton.dataset.sourceZoom;setSourceZoom(root,mode==='reset'?1:current+(mode==='in'?.25:-.25));const active=root?.querySelector('.source-box.active');if(active)centerSourceBox(root,active,false);return}const binaryButton=e.target.closest('[data-source-binary]');if(binaryButton){e.stopImmediatePropagation();const root=linkedRoot(binaryButton);const enabled=root?.querySelector('.source-image-viewport')?.classList.toggle('binary');binaryButton.classList.toggle('active',!!enabled);binaryButton.setAttribute('aria-pressed',String(!!enabled));return}const step=e.target.closest('[data-source-step]');if(step){e.stopImmediatePropagation();if(!step.disabled)stepSource(linkedRoot(step),step.dataset.sourceStep==='next'?1:-1);return}const box=e.target.closest('.source-box');if(box){e.stopImmediatePropagation();focusSourceBox(linkedRoot(box),box)}},true)
document.addEventListener('wheel',e=>{const viewport=e.target.closest('.source-image-viewport');if(!viewport)return;e.preventDefault();const root=linkedRoot(viewport);const canvas=root?.querySelector('.source-canvas');const current=Number(canvas?.dataset.zoom||1);zoomSourceAt(root,current+(e.deltaY<0?.15:-.15),e.clientX,e.clientY)},{passive:false});
let sourcePan=null;document.addEventListener('pointerdown',e=>{const viewport=e.target.closest('.source-image-viewport');if(!viewport||e.target.closest('.source-box')||e.button!==0)return;sourcePan={viewport,pointerId:e.pointerId,startX:e.clientX,startY:e.clientY,scrollLeft:viewport.scrollLeft,scrollTop:viewport.scrollTop};viewport.classList.add('dragging');viewport.setPointerCapture?.(e.pointerId);e.preventDefault()});document.addEventListener('pointermove',e=>{if(!sourcePan||sourcePan.pointerId!==e.pointerId)return;sourcePan.viewport.scrollLeft=sourcePan.scrollLeft-(e.clientX-sourcePan.startX);sourcePan.viewport.scrollTop=sourcePan.scrollTop-(e.clientY-sourcePan.startY)});function endSourcePan(e){if(!sourcePan||sourcePan.pointerId!==e.pointerId)return;sourcePan.viewport.classList.remove('dragging');sourcePan.viewport.releasePointerCapture?.(e.pointerId);sourcePan=null}document.addEventListener('pointerup',endSourcePan);document.addEventListener('pointercancel',endSourcePan);
function activateSource(root,item,source,autoZoom=false){if(!root||!item)return;source=String(source||1);const row=root.querySelector('[data-link-row][data-item="'+item+'"]');if(!row||row.hidden){toast('对应商品已删除');return}if(row.dataset.noSource==='true'){toast('人工新增商品无原图来源，左侧保持当前图片');return}const switcher=root.querySelector('[data-source-view-switch]');if(switcher&&!switcher.hidden)setSourceImageView(root,'corrected');root.querySelectorAll('[data-link-row]').forEach(x=>x.classList.remove('link-active'));row.classList.add('link-active');row.classList.remove('link-flash');requestAnimationFrame(()=>row.classList.add('link-flash'));root.querySelectorAll('.source-choice').forEach(x=>x.classList.toggle('active',x.dataset.sourceChoice===source));refreshSourceEnhancement(root,source);root.querySelectorAll('.source-box').forEach(x=>{x.style.display=x.dataset.source===source?'block':'none';x.classList.toggle('active',x.dataset.item===item&&x.dataset.source===source)});const box=root.querySelector('.source-box[data-item="'+item+'"][data-source="'+source+'"]');const count=Number(row.dataset.sourceCount||1);const index=root.querySelector('.source-current-index');const order=root.querySelector('.source-current-order');const detail=root.querySelector('.source-current-detail');if(index)index.textContent='来源 '+source+'/'+count;if(order)order.textContent=source==='2'?'销售订单B':'销售订单A';if(detail)detail.textContent=source==='2'?(row.dataset.sourceTwo||'第二个销售订单来源'):(row.dataset.sourceOne||row.dataset.original||'AI识别来源');root.querySelectorAll('.source-choice').forEach(x=>x.hidden=Number(x.dataset.sourceChoice)>count);if(box){refreshSourceStepper(root,box);centerSourceBox(root,box,autoZoom)}}
function openHistory(row){const modal=document.getElementById('auditChangeModal');if(!modal||!row)return;modal.querySelector('[data-history-original]').textContent=row.dataset.original||'—';modal.querySelector('[data-history-ai]').textContent=row.dataset.ai||'—';const current=row.querySelector('[data-current-name]')?.value||row.dataset.current||'—';const qty=row.querySelector('[data-current-qty]')?.value;modal.querySelector('[data-history-current]').textContent=current+(qty?' '+qty+(row.dataset.unit||''):'');modal.querySelector('[data-history-fields]').textContent=row.dataset.fields||'商品信息';modal.classList.add('open')}
function closeProductPickers(except){document.querySelectorAll('[data-product-picker].open').forEach(picker=>{if(picker===except)return;picker.classList.remove('open');picker.querySelector('[data-product-name]')?.setAttribute('aria-expanded','false')})}
function positionProductPicker(picker){const input=picker?.querySelector('input[data-product-name]');const menu=picker?.querySelector('.product-picker-menu');if(!input||!menu)return;const rect=input.getBoundingClientRect();const width=Math.min(1200,window.innerWidth-16);const left=Math.max(8,Math.min(rect.left,window.innerWidth-width-8));const menuHeight=Math.min(menu.scrollHeight||310,310);const below=rect.bottom+4;const top=below+menuHeight<=window.innerHeight-8?below:Math.max(8,rect.top-menuHeight-4);menu.style.width=width+'px';menu.style.left=left+'px';menu.style.top=top+'px'}
function openProductPicker(picker){if(!picker)return;closeProductPickers(picker);const currentDisplay=picker.querySelector('input[data-product-name]')?.value||'';picker.querySelectorAll('[data-product-option]').forEach(option=>option.classList.toggle('active',option.dataset.productDisplay===currentDisplay));picker.classList.add('open');picker.querySelector('input[data-product-name]')?.setAttribute('aria-expanded','true');positionProductPicker(picker)}
function filterProductOptions(input){const picker=input.closest('[data-product-picker]');if(!picker)return;const rawKeyword=input.value.trim().toLowerCase();const keyword=rawKeyword.includes(' ¥')?rawKeyword.split(' ¥')[0]:rawKeyword;let visible=0;picker.querySelectorAll('[data-product-option]').forEach(option=>{const matched=!keyword||option.textContent.toLowerCase().includes(keyword);option.hidden=!matched;if(matched)visible++});const empty=picker.querySelector('.product-picker-empty');if(empty)empty.hidden=visible>0;openProductPicker(picker)}
function chooseProductOption(option){const picker=option.closest('[data-product-picker]');const row=picker?.closest('tr');if(!picker||!row)return;const productInput=picker.querySelector('input[data-product-name]');const skuInput=row.querySelector('td.custom-field-col[data-field-id="system-sku-code"] input');const salesSpecInput=row.querySelector('td.custom-field-col[data-field-id="system-sales-spec"] input');const specInput=row.querySelector('td.custom-field-col[data-field-id="system-spec-description"] input');const descriptionInput=row.querySelector('td.custom-field-col[data-field-id="system-product-description"] input');const values=[[productInput,option.dataset.productDisplay],[skuInput,option.dataset.skuCode],[salesSpecInput,option.dataset.salesSpec],[specInput,option.dataset.specDescription],[descriptionInput,option.dataset.productDescription],[row.querySelector('input[data-product-price]'),option.dataset.price]];values.forEach(([input,value])=>{if(!input)return;input.value=value||'';input.dispatchEvent(new Event('input',{bubbles:true}))});if(productInput)productInput.dataset.productBaseName=option.dataset.productName||'';const unit=row.querySelector('.qty-unit [data-sales-unit]');if(unit)unit.textContent=option.dataset.salesUnit||'';row.dataset.current=option.dataset.productDisplay||'';row.dataset.productBaseName=option.dataset.productName||'';row.dataset.skuCode=option.dataset.skuCode||'';row.dataset.unit=option.dataset.salesUnit||'';row.dataset.salesSpec=option.dataset.salesSpec||'';row.dataset.specDescription=option.dataset.specDescription||'';row.dataset.productDescription=option.dataset.productDescription||'';row.dataset.quotationIds=option.dataset.quotationId||'';row.dataset.operationTime=quotationById(option.dataset.quotationId||'')?.operationTime||'';row.dataset.fields='商品名称、SKU编码、销售规格、商品规格、描述、报价单';row.classList.remove('normal-row-error');syncQuotationCell(row);picker.querySelectorAll('[data-product-option]').forEach(item=>item.classList.toggle('active',item===option));picker.classList.remove('open');productInput?.setAttribute('aria-expanded','false');toast('已选择 '+(option.dataset.productDisplay||'商品'))}
function orderDraftKey(){return 'ai-order-composite-product-fields:'+location.pathname.split('/').pop()}
function orderDraftRows(){return [...document.querySelectorAll('[data-order-table] tbody tr,[data-normal-item]')].filter((row,index,rows)=>rows.indexOf(row)===index)}
function orderRowSnapshot(row){const value=selector=>row.querySelector(selector)?.value??'';const skuInput=row.querySelector('td.custom-field-col[data-field-id="system-sku-code"] input');const salesSpecInput=row.querySelector('td.custom-field-col[data-field-id="system-sales-spec"] input');const specInput=row.querySelector('td.custom-field-col[data-field-id="system-spec-description"] input');const descriptionInput=row.querySelector('td.custom-field-col[data-field-id="system-product-description"] input');return {name:value('input[data-product-name]'),baseName:row.dataset.productBaseName||'',skuCode:skuInput?.value??row.dataset.skuCode??'',unit:row.dataset.unit||row.querySelector('.qty-unit [data-sales-unit]')?.textContent||'',salesSpec:salesSpecInput?.value??row.dataset.salesSpec??'',specDescription:specInput?.value??row.dataset.specDescription??'',productDescription:descriptionInput?.value??row.dataset.productDescription??'',quotationIds:row.dataset.quotationIds||'',operationTime:row.dataset.operationTime||'',qty:value('input[data-current-qty],input[data-normal-field="qty"]'),price:value('input[data-product-price]'),note:value('input[data-order-note]')}}
function applyOrderRowSnapshot(row,data){if(!row||!data)return;const fields={'input[data-product-name]':data.name,'td.custom-field-col[data-field-id="system-sku-code"] input':data.skuCode,'td.custom-field-col[data-field-id="system-sales-spec"] input':data.salesSpec,'td.custom-field-col[data-field-id="system-spec-description"] input':data.specDescription,'td.custom-field-col[data-field-id="system-product-description"] input':data.productDescription,'input[data-current-qty],input[data-normal-field="qty"]':data.qty,'input[data-product-price]':data.price,'input[data-order-note]':data.note};Object.entries(fields).forEach(([selector,value])=>{const input=row.querySelector(selector);if(input&&value!==undefined)input.value=value});const productInput=row.querySelector('input[data-product-name]');if(productInput&&data.baseName)productInput.dataset.productBaseName=data.baseName;if(data.baseName)row.dataset.productBaseName=data.baseName;if(data.skuCode!==undefined)row.dataset.skuCode=data.skuCode;if(data.unit){row.dataset.unit=data.unit;const unit=row.querySelector('.qty-unit [data-sales-unit]');if(unit)unit.textContent=data.unit}if(data.salesSpec!==undefined)row.dataset.salesSpec=data.salesSpec;if(data.specDescription!==undefined)row.dataset.specDescription=data.specDescription;if(data.productDescription!==undefined)row.dataset.productDescription=data.productDescription;if(data.quotationIds!==undefined)row.dataset.quotationIds=data.quotationIds;if(data.operationTime!==undefined)row.dataset.operationTime=data.operationTime;syncQuotationCell(row)}
function saveOrderDraft(){try{localStorage.setItem(orderDraftKey(),JSON.stringify(orderDraftRows().map(orderRowSnapshot)));toast('订单内容已保存，规格与描述已同步保存')}catch(error){toast('当前环境无法保存，请稍后重试')}}
function restoreOrderDraft(){try{const saved=JSON.parse(localStorage.getItem(orderDraftKey())||'null');if(!Array.isArray(saved))return;orderDraftRows().forEach((row,index)=>applyOrderRowSnapshot(row,saved[index]))}catch(error){}}
function addManualRow(root){const tbody=root?.querySelector('.item-edit-table tbody');const source=tbody?.querySelector('tr');if(!tbody||!source)return;const n=tbody.children.length+1;const row=source.cloneNode(true);row.dataset.item='manual-'+n;row.dataset.stableId='manual-'+n;row.dataset.noSource='true';row.dataset.current='新商品 ¥-/件';row.dataset.productBaseName='新商品';row.dataset.skuCode='';row.dataset.unit='件';row.dataset.salesSpec='1件/件';row.dataset.specDescription='请补充商品规格';row.dataset.productDescription='请补充描述';row.dataset.quotationIds='';row.dataset.operationTime='';row.removeAttribute('data-source-one');row.removeAttribute('data-source-two');row.querySelector('td:first-child').innerHTML='⋮⋮　<b>'+n+'</b>';row.querySelector('td:nth-child(2)').textContent='人工新增';row.querySelector('td:nth-child(6)').textContent='¥-';const set=(selector,value)=>{const input=row.querySelector(selector);if(input)input.value=value};set('input[data-product-name]','新商品 ¥-/件');set('td.custom-field-col[data-field-id="system-sku-code"] input','');set('td.custom-field-col[data-field-id="system-sales-spec"] input','1件/件');set('td.custom-field-col[data-field-id="system-spec-description"] input','请补充商品规格');set('td.custom-field-col[data-field-id="system-product-description"] input','请补充描述');set('input[data-current-qty]','1');set('input[data-product-price]','');set('input[data-order-note]','');const unit=row.querySelector('.qty-unit [data-sales-unit]');if(unit)unit.textContent='件';const picker=row.querySelector('[data-product-picker]');if(picker){picker.classList.remove('open');const productInput=picker.querySelector('input[data-product-name]');if(productInput)productInput.dataset.productBaseName='新商品';const menu=picker.querySelector('.product-picker-menu');if(menu)menu.innerHTML='<div class="product-picker-head"><span>商品名称</span><span>SKU编码</span><span>销售规格</span><span>商品规格</span><span>描述</span><span>报价单</span></div><div class="product-option active" role="option" tabindex="-1" data-product-option data-product-name="新商品" data-product-display="新商品 ¥-/件" data-sku-code="" data-sales-unit="件" data-sales-spec="1件/件" data-spec-description="请补充商品规格" data-product-description="请补充描述" data-quotation-id="" data-price=""><span class="product-option-title">新商品 ¥-/件</span><span class="product-option-field product-option-sku">—</span><span class="product-option-field">1件/件</span><span class="product-option-field">请补充商品规格</span><span class="product-option-field">请补充描述</span><span class="quotation-empty">—</span></div>'}tbody.appendChild(row);const modal=document.querySelector('[data-custom-field-modal]');if(modal)applyCustomFieldColumns(modal);row.querySelector('input[data-product-name]')?.focus()}
function createCustomFieldItem(id,name,source){source=source||'guanmai';const item=document.createElement('div');item.className='custom-field-selected-item';item.draggable=true;item.dataset.customFieldSelected='';item.dataset.fieldId=id;item.dataset.fieldName=name;item.dataset.fieldSource=source;const drag=document.createElement('span');drag.className='custom-field-drag';drag.setAttribute('aria-hidden','true');drag.textContent='⋮⋮';const order=document.createElement('span');order.className='custom-field-order';const label=document.createElement('span');label.className='custom-field-name';label.textContent=name;const remove=document.createElement('button');remove.className='custom-field-remove';remove.type='button';remove.dataset.customFieldRemove='';remove.setAttribute('aria-label','移除'+name);remove.textContent='×';item.append(drag,order,label,remove);return item}
function refreshCustomFieldModal(modal){if(!modal)return;const list=modal.querySelector('[data-custom-field-selected-list]');const items=[...list.querySelectorAll('[data-custom-field-selected]')];list.querySelector('.custom-field-empty')?.remove();items.forEach((item,index)=>{const order=item.querySelector('.custom-field-order');if(order)order.textContent=String(index+1)});if(!items.length){const empty=document.createElement('div');empty.className='custom-field-empty';empty.textContent='暂未选择展示字段';list.appendChild(empty)}modal.querySelectorAll('[data-custom-field-choice]').forEach(choice=>{choice.checked=items.some(item=>item.dataset.fieldId===choice.dataset.fieldId)})}
function addCustomFieldSelection(modal,id,name,source){const list=modal?.querySelector('[data-custom-field-selected-list]');if(!list||list.querySelector('[data-field-id="'+id+'"]'))return;list.querySelector('.custom-field-empty')?.remove();list.appendChild(createCustomFieldItem(id,name,source));refreshCustomFieldModal(modal)}
function removeCustomFieldSelection(modal,id){modal?.querySelector('[data-custom-field-selected][data-field-id="'+id+'"]')?.remove();refreshCustomFieldModal(modal)}
function setCustomFieldSelection(modal,ids){const list=modal?.querySelector('[data-custom-field-selected-list]');if(!list)return;list.innerHTML='';ids.forEach(id=>{const choice=modal.querySelector('[data-custom-field-choice][data-field-id="'+id+'"]');if(choice)list.appendChild(createCustomFieldItem(id,choice.dataset.fieldName,choice.dataset.fieldSource))});refreshCustomFieldModal(modal)}
function resetCustomFieldSelection(modal){setCustomFieldSelection(modal,['system-sales-spec','system-spec-description','system-product-description','system-quotation','system-spu','system-product-code','system-category-1','system-custom-code','demo-1','demo-2','demo-3','demo-5'])}
function customFieldCellValue(row,rowIndex,field){const productInput=row.querySelector('td:nth-child(3) input[data-product-name]');const productName=row.dataset.productBaseName||productInput?.dataset.productBaseName||productInput?.value.split(' ¥')[0]||'商品';const firstCategories=['蔬菜','饮料','粮油副食','厨房用品','肉禽蛋'];const secondCategories=['叶菜类','碳酸饮料','大米类','刀具类','鲜蛋类'];const customSamples={'demo-1':['绿源','可口可乐','十月稻田','双枪','正大'],'demo-2':['广东惠州','广东广州','黑龙江五常','浙江永康','广东清远'],'demo-3':['一级','标准','优选','合格品','A级'],'demo-4':['500g/袋','500ml/瓶','10kg/袋','30cm/把','30枚/板'],'demo-5':['纸箱','周转箱','编织袋','纸盒','蛋托'],'demo-6':['7天','12个月','18个月','长期','30天'],'demo-7':['冷藏','常温','阴凉干燥','常温','冷藏'],'demo-8':['KH-001','KH-002','KH-003','KH-004','KH-005'],'demo-9':['GY-1001','GY-1002','GY-1003','GY-1004','GY-1005'],'demo-10':['冷藏','常温','常温','常温','冷藏'],'demo-11':['去根','无需加工','无需加工','开刃','分拣'],'demo-12':['按斤','按箱','按袋','按件','按板'],'demo-13':['9%','13%','9%','13%','9%'],'demo-14':['当日批次','常规批次','近期批次','常规批次','当日批次'],'demo-15':['外观检查','包装检查','抽样检查','安全检查','破损检查'],'demo-16':['2026-07-20','2026-07-18','2026-07-10','2026-06-30','2026-07-20'],'demo-17':['2026-07-27','2027-07-18','2027-01-10','长期','2026-08-19'],'demo-18':['当天配送','常温配送','防潮运输','独立包装','轻拿轻放']};if(field.id==='system-sales-spec')return row.dataset.salesSpec||'';if(field.id==='system-spec-description')return row.dataset.specDescription||'';if(field.id==='system-product-description')return row.dataset.productDescription||'';if(field.id==='system-sku-code')return row.dataset.skuCode||'';if(field.id==='system-spu')return productName;if(field.id==='system-product-code')return 'SPU-'+String(rowIndex+1).padStart(4,'0');if(field.id==='system-category-1')return firstCategories[rowIndex%firstCategories.length];if(field.id==='system-category-2')return secondCategories[rowIndex%secondCategories.length];if(field.id==='system-custom-code')return 'ZD-'+String(rowIndex+1).padStart(3,'0');if(field.id==='system-quotation')return '默认报价单';return customSamples[field.id]?.[rowIndex%5]||''}
function applyCustomFieldColumns(modal){if(!modal)return;const fields=[...modal.querySelectorAll('[data-custom-field-selected]')].map(item=>({id:item.dataset.fieldId,name:item.dataset.fieldName,source:item.dataset.fieldSource}));document.querySelectorAll('table[data-custom-field-table]').forEach(table=>{const savedValues=new Map();[...table.tBodies].forEach(body=>[...body.rows].forEach(row=>{const values={};row.querySelectorAll('td.custom-field-col').forEach(cell=>{values[cell.dataset.fieldId]=cell.querySelector('input')?.value??cell.textContent});savedValues.set(row,values)}));table.querySelectorAll('.custom-field-col').forEach(cell=>cell.remove());const head=table.tHead?.rows[0];if(!head)return;const tableWidth=1250+fields.length*160;table.style.width=tableWidth+'px';table.style.minWidth=tableWidth+'px';fields.forEach(field=>{const th=document.createElement('th');th.className='custom-field-col';th.dataset.fieldId=field.id;th.textContent=field.name;th.title=field.name;head.insertBefore(th,head.lastElementChild)});[...table.tBodies].forEach(body=>[...body.rows].forEach((row,rowIndex)=>{fields.forEach(field=>{const td=document.createElement('td');td.className='custom-field-col';td.dataset.fieldId=field.id;if(field.id==='system-quotation')renderQuotationCell(row,td);else{const input=document.createElement('input');input.className='inline-input custom-field-input'+(['system-sales-spec','system-spec-description','system-product-description'].includes(field.id)?' field-editable':'');input.value=savedValues.get(row)?.[field.id]??customFieldCellValue(row,rowIndex,field);input.setAttribute('aria-label',field.name);if(field.id==='system-sku-code')input.readOnly=true;td.appendChild(input)}row.insertBefore(td,row.lastElementChild)})}))})}
function customFieldDragAfter(container,y){return [...container.querySelectorAll('[data-custom-field-selected]:not(.dragging)')].reduce((closest,item)=>{const box=item.getBoundingClientRect();const offset=y-box.top-box.height/2;return offset<0&&offset>closest.offset?{offset,element:item}:closest},{offset:Number.NEGATIVE_INFINITY,element:null}).element}
