document.addEventListener('click',e=>{const open=e.target.closest('[data-modal="customFieldModal"]');if(open){const modal=document.getElementById('customFieldModal');if(modal?.dataset.savedOrder)setCustomFieldSelection(modal,modal.dataset.savedOrder.split(',').filter(Boolean));const search=modal?.querySelector('[data-custom-field-search]');if(search){search.value='';search.dispatchEvent(new Event('input',{bubbles:true}))}}const remove=e.target.closest('[data-custom-field-remove]');if(remove){const item=remove.closest('[data-custom-field-selected]');removeCustomFieldSelection(remove.closest('[data-custom-field-modal]'),item.dataset.fieldId);return}const reset=e.target.closest('[data-custom-field-reset]');if(reset){resetCustomFieldSelection(reset.closest('[data-custom-field-modal]'));toast('已恢复默认字段');return}const save=e.target.closest('[data-custom-field-save]');if(save){const modal=save.closest('[data-custom-field-modal]');modal.dataset.savedOrder=[...modal.querySelectorAll('[data-custom-field-selected]')].map(item=>item.dataset.fieldId).join(',');applyCustomFieldColumns(modal);modal.classList.remove('open');toast('字段设置已保存，商品列表顺序已更新')}});
function syncEntryUsageState(){const badge=document.querySelector('[data-entry-usage]');if(!badge)return;const params=new URLSearchParams(location.search);const trialDays=Math.max(0,Number(params.get('trialDays')??badge.dataset.trialDays??0));const dailyRemaining=Math.max(0,Number(params.get('dailyRemaining')??badge.dataset.dailyRemaining??0));const dailyTotal=Math.max(0,Number(params.get('dailyTotal')??badge.dataset.dailyTotal??0));const trialValue=badge.querySelector('[data-trial-days-value]');const dailyValue=badge.querySelector('[data-daily-remaining-value]');if(trialValue)trialValue.textContent=trialDays+' 天';if(dailyValue)dailyValue.textContent=dailyRemaining+' / '+dailyTotal;badge.setAttribute('aria-label','试用剩余'+trialDays+'天，今日额度剩余'+dailyRemaining+'条，共'+dailyTotal+'条');const exhausted=trialDays<=0||dailyRemaining<=0;badge.classList.toggle('exhausted',exhausted);if(exhausted){document.getElementById('usageExhaustedModal')?.classList.add('open');document.querySelectorAll('.entry-composer button').forEach(button=>button.disabled=true)}}
