document.addEventListener('input',e=>{const input=e.target.closest('[data-customer-note-input],[data-customer-note-editor]');if(!input)return;const normalized=normalizeCustomerNote(input.value);if(input.value!==normalized)input.value=normalized;if(input.matches('[data-customer-note-editor]'))saveCustomerNote(input.closest('.modal-bg'),normalized);else{input.dataset.savedNote=normalized;syncCustomerNoteEmptyState(input.closest('.customer-note-card'),true)}});
