function tiltSelectedRow(value,label,type){return '<div class="tilt-choice" data-tilt-choice data-tilt-type="'+type+'" data-value="'+value+'"><span class="tilt-choice-name">'+label+'</span><button type="button" class="tilt-choice-remove" data-tilt-remove aria-label="移除'+label+'">×</button></div>'}
function syncTiltChoices(root){if(!root)return;['group','customer'].forEach(type=>{const list=root.querySelector('[data-tilt-list="'+type+'"]');if(!list)return;const selected=new Set([...list.querySelectorAll('[data-tilt-choice]')].map(choice=>choice.dataset.value));const rows=[...root.querySelectorAll('[data-feature-list="'+type+'"] .feature-pick-row')];list.innerHTML=rows.filter(row=>selected.has(row.dataset.value)).map(row=>{const spans=row.querySelectorAll('span');return tiltSelectedRow(row.dataset.value,spans[1]?.textContent||row.dataset.value,type)}).join('')||'<div class="feature-empty">暂无已选对象</div>';refreshTiltSelection(root)})}
function refreshTiltSelection(root){if(!root)return;['group','customer'].forEach(type=>{const list=root.querySelector('[data-tilt-list="'+type+'"]');const choices=[...(list?.querySelectorAll('[data-tilt-choice]')||[])];const select=root.querySelector('[data-tilt-add="'+type+'"]');const options=[...(select?.options||[])].filter(option=>option.value);const selected=new Set(choices.map(choice=>choice.dataset.value));const allToggle=root.querySelector('[data-tilt-all="'+type+'"]');const allEnabled=allToggle?.classList.contains('on')||false;const subset=root.querySelector('[data-tilt-subset="'+type+'"]');if(subset)subset.hidden=allEnabled;if(select)select.disabled=allEnabled;options.forEach(option=>{option.disabled=allEnabled||selected.has(option.value)});if(allToggle)allToggle.setAttribute('aria-pressed',String(allEnabled));const count=root.querySelector('[data-tilt-count="'+type+'"]');if(count)count.textContent=allEnabled?'全部':choices.length+'/'+options.length})}
function refreshFeaturePicker(root){if(!root)return;['group','customer'].forEach(type=>{const count=root.querySelector('[data-feature-count="'+type+'"]');const rows=root.querySelectorAll('[data-feature-list="'+type+'"] .feature-pick-row');if(count)count.textContent=rows.length;const all=root.querySelector('[data-feature-select-all="'+type+'"]');const select=root.querySelector('[data-feature-add="'+type+'"]');const total=select?[...select.options].filter(option=>option.value).length:0;const checked=total>0&&rows.length===total;if(all){all.classList.toggle('on',checked);const checkbox=all.querySelector('.checkbox');if(checkbox)checkbox.textContent=checked?'✓':''}});syncTiltChoices(root)}
