document.addEventListener('input',e=>{const name=e.target.closest('input[data-product-name]');if(name){filterProductOptions(name);name.closest('tr')?.classList.add('is-dirty');return}const editable=e.target.closest('td.custom-field-col[data-field-id="system-sales-spec"] input,td.custom-field-col[data-field-id="system-spec-description"] input,td.custom-field-col[data-field-id="system-product-description"] input');if(editable){const row=editable.closest('tr');const fieldId=editable.closest('td.custom-field-col')?.dataset.fieldId;if(row&&fieldId==='system-sales-spec')row.dataset.salesSpec=editable.value;if(row&&fieldId==='system-spec-description')row.dataset.specDescription=editable.value;if(row&&fieldId==='system-product-description')row.dataset.productDescription=editable.value;editable.classList.add('is-dirty');row?.classList.add('is-dirty')}});
document.addEventListener('keydown',e=>{const input=e.target.closest('input[data-product-name]');if(!input)return;const picker=input.closest('[data-product-picker]');const options=[...picker.querySelectorAll('[data-product-option]:not([hidden])')];if(e.key==='Escape'){picker.classList.remove('open');input.setAttribute('aria-expanded','false');return}if(!['ArrowDown','ArrowUp','Enter'].includes(e.key)||!options.length)return;e.preventDefault();let index=options.findIndex(option=>option.classList.contains('keyboard-active'));if(e.key==='Enter'){chooseProductOption(options[Math.max(0,index)]);return}options.forEach(option=>option.classList.remove('keyboard-active'));index=e.key==='ArrowDown'?Math.min(options.length-1,index+1):Math.max(0,index<0?options.length-1:index-1);options[index].classList.add('keyboard-active');options[index].scrollIntoView({block:'nearest'})});
