document.addEventListener('click',e=>{const toggle=e.target.closest('[data-feature-toggle]');if(toggle){const root=toggle.closest('[data-feature-settings]');const enabled=toggle.classList.contains('on');const scope=root.querySelector('.feature-scope');if(scope)scope.hidden=!enabled;root.querySelectorAll('[data-feature-add]').forEach(select=>select.disabled=!enabled);root.querySelectorAll('[data-feature-select-all]').forEach(button=>button.disabled=!enabled)}const selectAll=e.target.closest('[data-feature-select-all]');if(selectAll){const root=selectAll.closest('[data-feature-settings]');const type=selectAll.dataset.featureSelectAll;const list=root.querySelector('[data-feature-list="'+type+'"]');const select=root.querySelector('[data-feature-add="'+type+'"]');const options=[...select.options].filter(option=>option.value);const rows=list.querySelectorAll('.feature-pick-row');if(rows.length===options.length)list.innerHTML='<div class="feature-empty">暂无已选对象</div>';else list.innerHTML=options.map(option=>'<div class="feature-pick-row" data-value="'+option.value+'"><span class="checkbox checked">✓</span><span>'+option.textContent+'</span><button class="remove" data-feature-remove title="移出">×</button></div>').join('');refreshFeaturePicker(root);return}const remove=e.target.closest('[data-feature-remove]');if(remove){const root=remove.closest('[data-feature-settings]');const row=remove.closest('.feature-pick-row');const list=row.parentElement;row.remove();if(!list.querySelector('.feature-pick-row'))list.innerHTML='<div class="feature-empty">暂无已选对象</div>';refreshFeaturePicker(root);toast('已移出启用范围')}});
document.addEventListener('change',e=>{const select=e.target.closest('[data-feature-add]');if(!select||!select.value)return;const root=select.closest('[data-feature-settings]');const type=select.dataset.featureAdd;const list=root.querySelector('[data-feature-list="'+type+'"]');if(list.querySelector('[data-value="'+select.value+'"]'))toast('该对象已在启用范围内');else{list.querySelector('.feature-empty')?.remove();const label=select.options[select.selectedIndex].textContent;list.insertAdjacentHTML('beforeend','<div class="feature-pick-row" data-value="'+select.value+'"><span class="checkbox checked">✓</span><span>'+label+'</span><button class="remove" data-feature-remove title="移出">×</button></div>');refreshFeaturePicker(root);toast('已加入启用范围')}select.selectedIndex=0});
document.addEventListener('click',e=>{const tiltToggle=e.target.closest('[data-tilt-toggle]');if(tiltToggle){const root=tiltToggle.closest('[data-feature-settings]');const scope=root.querySelector('[data-tilt-scope]');if(scope)scope.hidden=!tiltToggle.classList.contains('on');return}const allToggle=e.target.closest('[data-tilt-all]');if(allToggle){const root=allToggle.closest('[data-feature-settings]');refreshTiltSelection(root);toast(allToggle.classList.contains('on')?'已适用全部'+(allToggle.dataset.tiltAll==='group'?'群聊':'客户'):'已改为指定'+(allToggle.dataset.tiltAll==='group'?'群聊':'客户'));return}const remove=e.target.closest('[data-tilt-remove]');if(remove){const root=remove.closest('[data-feature-settings]');const list=remove.closest('[data-tilt-list]');remove.closest('[data-tilt-choice]')?.remove();if(list&&!list.querySelector('[data-tilt-choice]'))list.innerHTML='<div class="feature-empty">暂无已选对象</div>';refreshTiltSelection(root);toast('已移出自动校正范围');return}const save=e.target.closest('[data-combined-feature-save]');if(!save)return;const root=save.closest('[data-feature-settings]');const tiltEnabled=root.querySelector('[data-tilt-toggle]')?.classList.contains('on');if(!tiltEnabled){toast('设置已保存：倾斜图片自动校正已关闭');return}const allGroups=root.querySelector('[data-tilt-all="group"]')?.classList.contains('on');const allCustomers=root.querySelector('[data-tilt-all="customer"]')?.classList.contains('on');const tiltGroups=root.querySelectorAll('[data-tilt-list="group"] [data-tilt-choice]').length;const tiltCustomers=root.querySelectorAll('[data-tilt-list="customer"] [data-tilt-choice]').length;if(!allGroups&&!allCustomers&&!tiltGroups&&!tiltCustomers){toast('请至少选择一个自动校正适用对象');return}const groupText=allGroups?'全部群聊':tiltGroups+' 个群聊';const customerText=allCustomers?'全部客户':tiltCustomers+' 个客户';toast('设置已保存：自动校正适用于 '+groupText+'、'+customerText)});
document.addEventListener('change',e=>{const select=e.target.closest('[data-tilt-add]');if(!select||!select.value)return;const root=select.closest('[data-feature-settings]');const type=select.dataset.tiltAdd;const list=root.querySelector('[data-tilt-list="'+type+'"]');if(list.querySelector('[data-tilt-choice][data-value="'+select.value+'"]'))toast('该对象已在校正范围内');else{list.querySelector('.feature-empty')?.remove();const label=select.options[select.selectedIndex].textContent;list.insertAdjacentHTML('beforeend',tiltSelectedRow(select.value,label,type));refreshTiltSelection(root);toast('已加入自动校正范围')}select.selectedIndex=0});
document.addEventListener('click',e=>{const trigger=e.target.closest('[data-help-trigger]');document.querySelectorAll('[data-help-tip].open').forEach(tip=>{if(!trigger||tip!==trigger.closest('[data-help-tip]')){tip.classList.remove('open');tip.querySelector('[data-help-trigger]')?.setAttribute('aria-expanded','false')}});if(!trigger)return;const tip=trigger.closest('[data-help-tip]');const open=tip.classList.toggle('open');trigger.setAttribute('aria-expanded',String(open));e.stopPropagation()});document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;document.querySelectorAll('[data-help-tip].open').forEach(tip=>{tip.classList.remove('open');tip.querySelector('[data-help-trigger]')?.setAttribute('aria-expanded','false')})});
document.addEventListener('click',e=>{const category=e.target.closest('[data-category-check]');if(category){const checked=category.classList.toggle('checked');category.textContent=checked?'✓':'';category.setAttribute('aria-pressed',String(checked));return}const remove=e.target.closest('[data-split-rule-delete]');if(remove){remove.closest('tr')?.remove();toast('拆单规则已删除')}});
function visibleNormalResultCards(root){return [...root.querySelectorAll('[data-normal-result-source]:not([hidden]) [data-normal-result-card]')]}
function refreshNormalSubmitState(root){if(!root)return;const groups=[...root.querySelectorAll('[data-normal-original-group]')];const previewed=groups.filter(group=>group.classList.contains('group-previewed')).length;const total=groups.length||1;const cards=visibleNormalResultCards(root);const submitted=cards.filter(card=>card.classList.contains('result-submitted')).length;const pending=cards.length-submitted;const countTag=root.querySelector('[data-normal-submit-count]');const status=root.querySelector('[data-normal-status]');const allPreviewed=groups.length>0&&previewed===total;root.classList.toggle('preview-ready',allPreviewed);const submitAll=root.querySelector('[data-normal-result-submit-all]');if(submitAll)submitAll.hidden=pending===0;if(cards.length){if(countTag)countTag.textContent=submitted+'/'+cards.length+' 组已提交';if(allPreviewed&&pending===0){root.classList.add('submitted');if(status){status.textContent='已提交';status.className='tag green'}}else{root.classList.remove('submitted');if(status){status.textContent=pending?'待提交':'待处理';status.className='tag orange'}}return}if(countTag)countTag.textContent='0/'+total+' 组待预览';if(status){status.textContent='待处理';status.className='tag orange'}}
function markNormalOriginalPreviewed(group){if(!group||group.classList.contains('group-previewed'))return;group.classList.add('group-previewed')}
function normalSubmitTargets(root,scope,sourceGroup){const originals=[...root.querySelectorAll('[data-normal-original-group]')];return scope==='all'?originals.filter(group=>!group.classList.contains('group-previewed')):originals.filter(group=>group.dataset.normalOriginalGroup===sourceGroup&&!group.classList.contains('group-previewed'))}
function normalBlockingRows(root,scope,sourceGroup){return normalSubmitTargets(root,scope,sourceGroup).flatMap(group=>[...group.querySelectorAll('[data-normal-item]')].filter(row=>rowQuotationIds(row).length!==1||!row.dataset.operationTime))}
function normalResultMode(root){return root?.dataset.categoryTiming==='confirm'?'category-time':'time'}
function showNormalSplitResults(root,targets,mode){targets.forEach(group=>{const source=group.dataset.normalOriginalGroup;root.querySelectorAll('[data-normal-result-source="'+source+'"]').forEach(section=>{section.hidden=section.dataset.resultMode!==mode})});root.classList.add('split-result');root.dataset.splitResult=mode==='category-time'?'category-then-operation-time':'operation-time';visibleNormalResultCards(root).forEach((card,index)=>{card.querySelectorAll('[data-normal-result-name]').forEach(name=>name.textContent='订单'+(index+1)+'组')});const first=targets[0]&&root.querySelector('[data-normal-result-source="'+targets[0].dataset.normalOriginalGroup+'"][data-result-mode="'+mode+'"]');requestAnimationFrame(()=>first?.scrollIntoView({behavior:'smooth',block:'start'}))}
function previewNormalOrder(root,scope,sourceGroup){if(!root)return;const targets=normalSubmitTargets(root,scope,sourceGroup);if(!targets.length)return;const mode=normalResultMode(root);const countKey=mode==='category-time'?'categoryTimeSplitCount':'timeSplitCount';const resultCount=targets.reduce((sum,group)=>sum+Number(group.dataset[countKey]||0),0);showNormalSplitResults(root,targets,mode);targets.forEach(markNormalOriginalPreviewed);refreshNormalSubmitState(root);toast('已生成 '+resultCount+' 个拆单订单预览，请核对后确认提交')}
function submitNormalResultCard(root,card,notify=true){if(!root||!card||card.classList.contains('result-submitted'))return;card.classList.add('result-submitted');const status=card.querySelector('[data-normal-result-status]');if(status){status.textContent='已提交';status.className='tag green'}const button=card.querySelector('[data-normal-result-submit]');if(button){button.disabled=true;button.hidden=true}refreshNormalSubmitState(root);if(notify)toast('该订单组已确认提交')}
function submitAllNormalResults(root){const pending=visibleNormalResultCards(root).filter(card=>!card.classList.contains('result-submitted'));if(!pending.length)return;pending.forEach(card=>submitNormalResultCard(root,card,false));refreshNormalSubmitState(root);toast('全部拆单订单已确认提交')}
document.addEventListener('click',e=>{const resultSubmit=e.target.closest('[data-normal-result-submit]');if(resultSubmit){const root=resultSubmit.closest('.normal-order-detail');submitNormalResultCard(root,resultSubmit.closest('[data-normal-result-card]'));return}const resultSubmitAll=e.target.closest('[data-normal-result-submit-all]');if(resultSubmitAll){submitAllNormalResults(resultSubmitAll.closest('.normal-order-detail'));return}const timing=e.target.closest('[data-split-timing]');if(timing){const root=timing.closest('[data-split-timing-settings]');root.querySelectorAll('[data-split-timing]').forEach(option=>{const active=option===timing;option.classList.toggle('active',active);option.setAttribute('aria-pressed',String(active))});root.dataset.selectedTiming=timing.dataset.splitTiming;toast('已选择“'+timing.querySelector('strong').textContent.trim()+'”');return}const open=e.target.closest('[data-normal-confirm]');if(!open)return;const root=open.closest('.normal-order-detail');const scope=open.dataset.normalConfirm||'group';const sourceGroup=open.closest('[data-normal-original-group]')?.dataset.normalOriginalGroup||'';const blocking=normalBlockingRows(root,scope,sourceGroup);root.querySelectorAll('.normal-row-error').forEach(row=>row.classList.remove('normal-row-error'));if(blocking.length){blocking.forEach(row=>row.classList.add('normal-row-error'));blocking[0].scrollIntoView({behavior:'smooth',block:'center'});toast('请先将标红商品修改为唯一报价单商品，再确认提交');return}previewNormalOrder(root,scope,sourceGroup)});
document.addEventListener('input',e=>{if(!e.target.matches('[data-track-source]'))return;const row=e.target.closest('[data-link-row]');if(row)row.dataset.fields=e.target.dataset.field||'商品信息'});
document.addEventListener('input',e=>{const input=e.target.closest('[data-prompt-customer-search]');if(!input)return;const keyword=input.value.trim().toLowerCase();input.closest('[data-panel="customerView"]')?.querySelectorAll('tbody tr').forEach(row=>row.hidden=!!keyword&&!row.textContent.toLowerCase().includes(keyword))});
document.addEventListener('click',e=>{const option=e.target.closest('[data-order-visibility-mode]');if(option){const root=option.closest('[data-order-visibility]');const selected=option.dataset.orderVisibilityMode;root.querySelectorAll('[data-order-visibility-mode]').forEach(item=>{const active=item===option;item.classList.toggle('active',active);item.setAttribute('aria-checked',String(active))});const save=root.querySelector('[data-order-visibility-save]');if(save)save.disabled=selected===root.dataset.savedMode;return}const save=e.target.closest('[data-order-visibility-save]');if(!save)return;const root=save.closest('[data-order-visibility]');const selected=root.querySelector('[data-order-visibility-mode].active')?.dataset.orderVisibilityMode||'assigned';root.dataset.savedMode=selected;root.querySelectorAll('[data-order-visibility-mode]').forEach(item=>{const effective=item.dataset.orderVisibilityMode===selected;item.classList.toggle('effective',effective);const status=item.querySelector('[data-order-visibility-effective]');if(status)status.hidden=!effective});save.disabled=true;toast('订单查看范围已保存')});
const reminderDayNames=['周一','周二','周三','周四','周五','周六','周日'];
function reminderRows(){return [...document.querySelectorAll('[data-reminder-row]')]}
function visibleReminderRows(){return reminderRows().filter(row=>!row.hidden)}
function syncReminderSelection(){const rows=reminderRows();const visible=visibleReminderRows();const selected=rows.filter(row=>row.querySelector('[data-reminder-row-check]')?.checked);const selectAll=document.querySelector('[data-reminder-select-all]');if(selectAll){const visibleSelected=visible.filter(row=>row.querySelector('[data-reminder-row-check]')?.checked).length;selectAll.checked=visible.length>0&&visibleSelected===visible.length;selectAll.indeterminate=visibleSelected>0&&visibleSelected<visible.length}const count=document.querySelector('[data-reminder-selected-count]');if(count)count.textContent=selected.length;const batch=document.querySelector('[data-reminder-batch]');if(batch)batch.disabled=selected.length===0}
function setReminderBatchMode(enabled){const panel=document.querySelector('.groups-panel');const bar=document.querySelector('[data-group-batch-bar]');const trigger=document.querySelector('[data-reminder-enter-batch]');if(!panel||!bar)return;panel.classList.toggle('batch-mode',enabled);bar.hidden=!enabled;if(trigger)trigger.hidden=enabled;if(!enabled)reminderRows().forEach(row=>{const check=row.querySelector('[data-reminder-row-check]');if(check)check.checked=false});syncReminderSelection()}
function filterReminderRows(){const search=document.querySelector('[data-reminder-search]');if(!search)return;const keyword=(search.value||'').trim().toLowerCase();reminderRows().forEach(row=>{row.hidden=!!keyword&&!String(row.dataset.group||'').toLowerCase().includes(keyword)});syncReminderSelection()}
function updateReminderCharCount(root=document){const message=root.querySelector('[data-reminder-message]');const count=root.querySelector('[data-reminder-char-count]');if(message&&count)count.textContent=Array.from(message.value).length}
function populateReminderModal(row,mode){const modal=document.querySelector('[data-reminder-modal]');if(!modal)return;const batch=mode==='batch';modal.dataset.mode=batch?'batch':'single';modal.dataset.editId=batch?'':row?.dataset.id||'';const title=modal.querySelector('[data-reminder-modal-title]');if(title)title.textContent=batch?'批量设置群聊催单':'修改群聊催单设置';const enabled=batch?true:row?.dataset.enabled==='true';const enabledControl=modal.querySelector('[data-reminder-enabled]');enabledControl?.classList.toggle('on',enabled);enabledControl?.setAttribute('aria-checked',String(enabled));const days=batch?['1','2','3','4','5']:String(row?.dataset.days||'').split(',').filter(Boolean);modal.querySelectorAll('[data-reminder-day]').forEach(day=>{const active=days.includes(day.dataset.reminderDay);day.classList.toggle('active',active);day.setAttribute('aria-pressed',String(active))});const time=modal.querySelector('[data-reminder-time]');if(time)time.value=batch?'16:30':row?.dataset.time||'16:30';const message=modal.querySelector('[data-reminder-message]');if(message)message.value=batch?'亲亲~您好！今天还没有看到您的订单哦~记得及时下单哟~😊':row?.dataset.message||'';updateReminderCharCount(modal)}
function reminderValues(modal){return{enabled:modal.querySelector('[data-reminder-enabled]')?.classList.contains('on')||false,days:[...modal.querySelectorAll('[data-reminder-day].active')].map(day=>day.dataset.reminderDay),time:modal.querySelector('[data-reminder-time]')?.value||'',message:modal.querySelector('[data-reminder-message]')?.value.trim()||''}}
function applyReminderValues(row,values){row.dataset.enabled=String(values.enabled);row.dataset.days=values.days.join(',');row.dataset.time=values.time;row.dataset.message=values.message;const status=row.querySelector('[data-reminder-status]');if(status)status.innerHTML=values.enabled?'<span class="tag green">已启用</span>':'<span class="tag ">已停用</span>'}
function validateReminderValues(values){if(values.enabled&&!values.days.length){toast('请至少选择一个日常下单日期');return false}if(values.enabled&&!values.time){toast('请设置提醒时间');return false}if(values.enabled&&!values.message){toast('请输入催单话术');return false}return true}
document.addEventListener('click',e=>{const enter=e.target.closest('[data-reminder-enter-batch]');if(enter){setReminderBatchMode(true);return}const cancel=e.target.closest('[data-reminder-cancel-batch]');if(cancel){setReminderBatchMode(false);return}const edit=e.target.closest('[data-reminder-edit]');if(edit){populateReminderModal(edit.closest('[data-reminder-row]'),'single');return}const batch=e.target.closest('[data-reminder-batch]');if(batch){populateReminderModal(null,'batch');return}const day=e.target.closest('[data-reminder-day]');if(day){const active=day.classList.toggle('active');day.setAttribute('aria-pressed',String(active));return}const enabled=e.target.closest('[data-reminder-enabled]');if(enabled){enabled.setAttribute('aria-checked',String(enabled.classList.contains('on')));return}const detailSave=e.target.closest('[data-reminder-detail-save]');if(detailSave){const detail=detailSave.closest('[data-reminder-detail]');const values=reminderValues(detail);if(!validateReminderValues(values))return;detail.dataset.enabled=String(values.enabled);detail.dataset.days=values.days.join(',');detail.dataset.time=values.time;toast('当前群聊的催单设置已保存');return}const save=e.target.closest('[data-reminder-save]');if(!save)return;const modal=save.closest('[data-reminder-modal]');const values=reminderValues(modal);if(!validateReminderValues(values))return;const targets=modal.dataset.mode==='batch'?reminderRows().filter(row=>row.querySelector('[data-reminder-row-check]')?.checked):reminderRows().filter(row=>row.dataset.id===modal.dataset.editId);targets.forEach(row=>applyReminderValues(row,values));modal.classList.remove('open');filterReminderRows();if(modal.dataset.mode==='batch')setReminderBatchMode(false);else syncReminderSelection();toast(modal.dataset.mode==='batch'?'已批量保存 '+targets.length+' 个群聊的催单设置':'群聊催单设置已保存')});
document.addEventListener('change',e=>{if(e.target.matches('[data-reminder-select-all]')){visibleReminderRows().forEach(row=>{const check=row.querySelector('[data-reminder-row-check]');if(check)check.checked=e.target.checked});syncReminderSelection();return}if(e.target.matches('[data-reminder-row-check]'))syncReminderSelection()});
document.addEventListener('input',e=>{if(e.target.matches('[data-reminder-search]'))filterReminderRows();if(e.target.matches('[data-reminder-message]'))updateReminderCharCount(e.target.closest('[data-reminder-modal],[data-reminder-detail]')||document)});
