function splitItemsByCategoryRule(items){const grouped=new Map();items.forEach(item=>{const rule=categoryRuleForItem(item);if(!grouped.has(rule.id))grouped.set(rule.id,{rule,items:[]});grouped.get(rule.id).items.push(item)});return [...grouped.values()].sort((a,b)=>normalCategoryRuleConfig.findIndex(rule=>rule.id===a.rule.id)-normalCategoryRuleConfig.findIndex(rule=>rule.id===b.rule.id)).map(({rule,items:members},index)=>{const amount='¥'+members.reduce((sum,item)=>sum+Number(item[6]||0),0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});return [rule.id,`分类订单${index+1}组 · ${rule.title}`,members.map(item=>item[0]),amount]})}
function splitItemsByCategoryThenOperationTime(items,sourceGroup='1'){const results=[];splitItemsByCategoryRule(items).forEach(([,title,itemIds])=>{const members=items.filter(item=>itemIds.includes(item[0]));splitItemsByOperationTime(members,title,sourceGroup).forEach(rule=>results.push(rule))});return results}
