function normalResultCard(rule,index){const [,itemIds,operationTime,amount]=rule;const items=normalOrderItems.filter(item=>itemIds.includes(item[0]));const groupName=`订单${index+1}组`;return `<section class="normal-result-card" data-normal-result-card><div class="normal-result-card-head"><strong data-normal-result-name>${groupName}</strong>${tag(items.length+' 个商品','blue')}${tag(amount,'red')}<span class="tag orange" data-normal-result-status>待提交</span><div class="normal-result-card-actions">${btn('确认提交','primary','data-normal-result-submit')}</div></div>${normalResultOrderInfo(operationTime)}${normalResultTable(items)}</section>`}
function normalResultSource(sourceGroup,sourceTitle,items){const timeRules=splitItemsByOperationTime(items,sourceTitle,sourceGroup);const categoryTimeRules=splitItemsByCategoryThenOperationTime(items,sourceGroup);return `<div class="normal-result-source" data-normal-result-source="${sourceGroup}" data-result-mode="time" hidden>${timeRules.map((rule,index)=>normalResultCard(rule,index,sourceTitle)).join('')}</div><div class="normal-result-source" data-normal-result-source="${sourceGroup}" data-result-mode="category-time" hidden>${categoryTimeRules.map((rule,index)=>normalResultCard(rule,index,sourceTitle)).join('')}</div>`}
