// 经营决策大屏
const miniMetric=(title,values)=>`<div class="multi-item"><b>${title}</b><div class="mini-metrics">${values.map(([l,v,c=''])=>`<span><small>${l}</small><b class="${c}">${v}</b></span>`).join('')}</div></div>`;
const decisionBody=`<div class="plain-page"><div class="dash-title"><div><h1>◴ 经营决策大屏</h1><p>从单纯看明细到看诊断与管资产 · 一屏总览 AI 商业价值</p></div><div><span class="muted">时间范围　</span><div class="seg compact" style="display:inline-flex"><button class="active">今日实时</button><button>昨日</button><button>近 7 天</button><button>近 30 天</button><button>自定义</button></div></div></div>
 <div class="section-title"><span class="section-num">01</span><h2>核心指标概览</h2><span>— 资产、经营与降本视角</span></div><section class="quota-assets"><div class="quota-assets-head">AI 额度资产与消耗</div><div class="quota-assets-body"><div class="quota-asset"><span class="label">剩余可用条数</span><b class="blue">99,260</b>${tag('额度充足','orange')}</div><div class="quota-asset"><span class="label">累计充值总额度</span><b>101,170</b><small class="muted">历史累计</small></div><div class="quota-asset"><span class="label">今日提交总条数</span><b>0</b><small class="muted">0:00 起统计</small></div><div class="quota-asset"><span class="label">今日已消耗条数</span><b class="red">0</b><small class="muted">成功扣费</small></div></div></section>
 <div class="metric-row" style="margin-top:18px"><div class="metric-card"><span class="label blue">ϟ　累计节省工时</span><b class="green">0.0 人/日</b><small class="muted">≈ 全职接单员</small></div><div class="metric-card"><span class="label blue">♢　商品识别率</span><b class="blue">0.0 %</b><small class="muted">商品识别率</small></div><div class="metric-card"><span class="label blue">♙　活跃群占比</span><b>0 / 5</b><small class="muted">下单群 / 绑定群</small></div><div class="metric-card"><span class="label blue">⌁　订单提交数</span><b>0 / 0</b><small class="muted">提交 / 生成</small></div><div class="metric-card"><span class="label blue">☼　新增记忆数</span><b class="blue">0</b><small class="muted">纠错 + 习惯</small></div></div>
 <div class="section-title"><span class="section-num">02</span><h2>多模态分析与趋势</h2><span>— 算法表现视角</span></div><section class="multi-card"><div class="multi-head">多模态下单类型分析</div><div class="multi-grid">${miniMetric('纯文本下单',[['接收订单','0'],['人工干预','0','red'],['准确率','-','blue']])}${miniMetric('图片下单',[['接收订单','0'],['人工干预','0','red'],['准确率','-','orange']])}${miniMetric('文件下单',[['接收订单','0'],['人工干预','0','red'],['准确率','-','green']])}${miniMetric('其他类型',[['接收订单','0'],['人工干预','0','red'],['准确率','-']])}</div></section>
 <div class="section-title"><span class="section-num">03</span><h2>客户与群聊经营洞察</h2><span>— 业务增长视角</span></div><section class="multi-card"><div class="multi-grid">${miniMetric('活跃客户',[['今日活跃','0'],['环比','-'],['总客户','24']])}${miniMetric('群聊转化',[['下单群','0'],['绑定群','5'],['转化率','0%']])}${miniMetric('AI 记忆资产',[['今日新增','0'],['累计修正','141'],['常购商品','1320']])}${miniMetric('人工审核',[['待处理','16'],['已完成','63'],['失败','7']])}</div></section></div>`;
add('decision-dashboard.html','经营决策大屏',decisionBody);

// 设置
function settingTabs(active,onMain=false){const tab=(key,label)=>onMain?`<button class="settings-tab ${active===key?'active':''}" data-subtab="${key}">${label}</button>`:`<a class="settings-tab ${active===key?'active':''}" href="settings.html#${key}">${label}</a>`;return `<div class="settings-tabs">${tab('channels','信道设置')}${tab('notice','通知设置')}<a class="settings-tab module-link ${active==='replies'?'active':''}" href="settings-replies.html">回复设置</a>${tab('function','功能设置')}</div>`}
const channelRows=[['微信录单主信道',tag('微信','blue'),tag('在线','green'),sw(true),'AI录单测试群-BD 等 4 个群聊','详情'],['邮件录单信道',tag('邮件','purple'),tag('在线','green'),sw(true),'orders@demo.com','详情'],['Web 录单',tag('Web','blue'),tag('在线','green'),sw(true),'嵌入式录单入口','详情']];
const channelPanel=`<div class="toolbar" style="margin:17px 0 12px"><b>信道列表</b><span class="spacer"></span>${btn('新增信道','primary','data-toast="打开新增信道"')}</div>${table(['信道名称','类型','连接状态','启用','关联对象','操作'],channelRows)}`;
const noticePanel=`<div style="padding:22px 8px;max-width:820px"><div class="form-grid">${field('任务失败通知',`<div class="toolbar">${sw(true)}<span>识别或提交失败时通知管理员</span></div>`)}${field('额度不足通知',`<div class="toolbar">${sw(true)}<span>剩余额度低于阈值时通知</span></div>`)}${field('通知邮箱','<input class="ctrl" value="admin@example.com">')}${field('额度阈值','<input class="ctrl" value="1000">')}</div><div style="margin-top:20px">${btn('保存','primary','data-toast="通知设置已保存"')}</div></div>`;
